def nxt(w,d):
    return ''.join(chr((ord(c)-65+x)%26+65) for c,x in zip(w,d))
d=[-2,4,-2,4]
s=['BHVC']
for i in range(4): s.append(nxt(s[-1],d))
assert s[1:3]==['ZLTG','XPRK'] and s[4]=='TXNS'
r=s[3]
assert r=='VTPO' and r not in ('VTPN','VPTO','VPTN')

t=[None,'O',None,'O',None,None,'O',None,'P',None,'O',None]
def fill(x):
    s=list(t);it=iter(x)
    return ''.join(c if c else next(it) for c in s)
o={'A':'PPOOPOP','B':'OOPPPOO','C':'OPOPOOP','D':'PPOOOPO'}
ok=[k for k,v in o.items() if fill(v)=='OOP'*4]
assert ok==['C']
